let results = [];

for (let i = 0; i < items.length; i++) {
  let raw = items[i].json.output || "";

  // Chuyển sang string nếu lỡ bị là object
  raw = String(raw);

  // 1. Loại bỏ các ký tự JSON-dangerous
  let clean = raw
    .replace(/[�-]+/g, " ")      // control chars
    .replace(/[
	]+/g, " ")             // xuống dòng, tab
    .replace(/\\/g, "")                     // dấu \
    .replace(/"/g, "'")                     // chuyển " → '
    .replace(/`+/g, "")                     // dấu backtick `
    .replace(/“|”/g, "'")                   // dấu ngoặc kép cong
    .replace(/‘|’/g, "'")                   // ngoặc đơn cong
    .replace(/[  ]/g, " ")        // unicode line separator
    .replace(/<[^>]*>/g, "")                // loại bỏ HTML tag nếu có
    .replace(/\s{2,}/g, " ")                // gom nhiều space thành 1
    .trim();

  // 2. Tránh ký tự gây sập cURL
  clean = clean.replace(/&/g, " và ");

  results.push({
    json: {
      clean_text: clean
    }
  });
}

return results;

