// Node: Merge Text + Vision Analysis for AI Agent
// Đặt SAU node "Parse Vision Result"
// Mục đích: Gộp text message + vision analysis để gửi vào AI Agent

// Lấy data từ các node
const visionResult = items[0].json; // Từ Parse Vision Result
const postgresResult = $('Execute a SQL query2').all(); // Text từ Postgres
const imageData = $('Edit Fields - Image').item.json;

// Biến để lưu text message (nếu có)
let textMessage = null;
let hasRelatedText = false;

// Check xem có text message không
if (postgresResult && postgresResult.length > 0) {
  const textRow = postgresResult[0].json;

  // Parse message_data
  // Dựa vào Image 1, message_data là string "ơm này là gì"
  let messageText = textRow.message_data;

  // Nếu message_data là JSON string, parse nó
  if (typeof messageText === 'string' && messageText.startsWith('{')) {
    try {
      const parsed = JSON.parse(messageText);
      messageText = parsed?.body?.entry?.[0]?.messaging?.[0]?.message?.text || messageText;
    } catch (e) {
      // Nếu parse lỗi, giữ nguyên string
    }
  }

  textMessage = messageText;

  if (textMessage && textMessage.trim().length > 0) {
    hasRelatedText = true;
    console.log('✅ Found related text:', textMessage);
    console.log('📸 Vision analysis:', visionResult.image_type);
  }
}

// Return merged data cho AI Agent
return [{
  json: {
    // IDs
    sender_id: visionResult.sender_id || imageData.sender_id,
    receiver_id: visionResult.receiver_id || imageData.receiver_id,

    // Vision analysis results
    image_type: visionResult.image_type,
    menu_name: visionResult.menu_name,
    price: visionResult.price,
    caption: visionResult.caption || imageData.caption || '',

    // Related text message
    related_text: textMessage,
    has_related_text: hasRelatedText,

    // PROMPT cho AI Agent - QUAN TRỌNG!
    user_message: hasRelatedText 
      ? `User hỏi: "${textMessage}" và gửi kèm ảnh.` 
      : 'User gửi ảnh.',

    image_analysis_context: `Phân tích ảnh: Loại=${visionResult.image_type}, Nội dung=${visionResult.menu_name}, Thông tin=${visionResult.price}`,

    // Full context for AI
    full_context: hasRelatedText
      ? `User vừa hỏi: "${textMessage}"\n\nSau đó gửi ảnh này.\n\nKết quả phân tích ảnh:\n- Loại: ${visionResult.image_type}\n- Nội dung: ${visionResult.menu_name}\n- Thông tin: ${visionResult.price}\n\nHãy trả lời câu hỏi của user dựa trên ảnh này.`
      : `User gửi ảnh.\n\nKết quả phân tích ảnh:\n- Loại: ${visionResult.image_type}\n- Nội dung: ${visionResult.menu_name}\n- Thông tin: ${visionResult.price}\n\nHãy mô tả và tư vấn về ảnh này.`
  }
}];

