// Node: Classify Image-Related Messages
// Mục đích: Phân loại tin nhắn có đề cập đến ảnh/hình hay không

const message = ($json.message || '').toLowerCase().trim();

// Danh sách từ khóa liên quan đến ảnh
const imageKeywords = [
  'ảnh',
  'hình',
  'photo',
  'picture',
  'pic',
  'image',
  'ảnh này',
  'trong ảnh',
  'xem ảnh',
  'ảnh trên',
  'ảnh dưới',
  'hình trên',
  'hình dưới',
  'phía trên',
  'phía dưới',
  'sản phẩm trong ảnh',
  'trong hình',
  'ở ảnh',
  'ở hình',
  'hình ảnh'
];

// Check xem message có chứa từ khóa không
let hasImageKeyword = false;
let matchedKeyword = null;

for (const keyword of imageKeywords) {
  if (message.includes(keyword)) {
    hasImageKeyword = true;
    matchedKeyword = keyword;
    break;
  }
}

// Phân loại
let category;
let description;

if (hasImageKeyword) {
  // NHÁNH 1: Có đề cập đến ảnh
  category = 'image_related';
  description = 'Yes';
} else {
  // NHÁNH 2: Không đề cập đến ảnh
  category = 'text_only';
  description = 'No';
}

return [{
  json: {
    ...($json),
    category: category,
    description: description,
    matched_keyword: matchedKeyword,
    original_message: message,
    is_image_related: hasImageKeyword
